def _is_integer(value: Union[int, float]) -> bool:
    if isinstance(value, int) or (hasattr(value, "is_integer") and value.is_integer()):
        return True
    elif isinstance(value, float):
        return False

    err_msg = f"`value` must be of type `int` or `float`, is {type(value)}"
    raise TypeError(err_msg)

from typing import Union


def num(number_as_string: str) -> Union[int, float]:
    """Convert given string to an integer or a float.

    """

    try:
        return int(number_as_string)
    except ValueError:
        return float(number_as_string)
    except Exception:
        raise ValueError('Expected integer or floating point number.') from None
